// ---- Filter prototype helpers (Site look = Acme Bakery's Design system, raw hex) ----
const SC={bg:"#FFFBF5",ink:"#2B1D14",soft:"#7A6555",line:"#E9DCCB",surf:"#F5EBDD",acc:"#9A3412",accSoft:"#FCE7D6",white:"#FFFFFF"};
const STRUCT_SECTIONS=a=>[
 {label:"Content",items:[["layout-dashboard","Overview"],["file-text","Pages",{badge:12}],["shopping-basket","Products",{badge:48}],["newspaper","Blog posts",{badge:24}],["image","Media"],["inbox","Forms",{tag:"5 new",tagKind:"info"}],["sliders-horizontal","Globals"],["languages","Translations"]]},
 {label:"Structure",tag:"Staff only",items:[["database","Post Types & Fields"],["layout-template","Templates"],["component","Components"],["palette","Design system"],["square-stack","Popups"],["list-filter","Filters"]]}];
const SITE_F=()=>({av:"AB",avFill:"#D97706",title:"Acme Bakery",subtitle:"Acme Ltd · acmebakery.ie",sections:STRUCT_SECTIONS(),footer:[["settings","Site settings"]],active:"Filters"});
function stx(p,c,o={}){return tx(p,c,{fill:SC.ink,...o});}
function mono(p,c,o={}){const b=fr(p,"Code "+c,{padding:[2,6],cornerRadius:4,fill:o.bg||"$muted",alignItems:"center"});tx(b,c,{fontSize:o.fs||11,fill:o.c||"$fg",fontFamily:"Roboto Mono"});return b;}
function seg(p,items,active,o={}){const s=fr(p,"Segmented",{padding:3,gap:2,cornerRadius:8,fill:"$muted",...(o.w?{width:"fill_container"}:{})});for(const it of items){const a=it==active;const b=fr(s,"Seg "+it,{padding:[4,10],cornerRadius:6,justifyContent:"center",...(o.w?{width:"fill_container"}:{}),...(a?{fill:"$bg"}:{})});tx(b,it,{fontSize:12,fontWeight:"500",fill:a?"$fg":"$muted-fg"});}return s;}
function lbl(p,t,hint){const g=fr(p,"L "+t,{layout:"vertical",gap:2,width:"fill_container"});tx(g,t,{fontWeight:"500"});if(hint)tx(g,hint,{fontSize:12,fill:"$muted-fg",textGrowth:"fixed-width",width:"fill_container"});return g;}
function note(p,t,o={}){const n=fr(p,"Note",{width:o.w||"fill_container",padding:[8,10],gap:8,cornerRadius:8,fill:"$info-bg",alignItems:"start"});ic(n,o.icon||"info",{width:14,height:14,fill:"$info"});tx(n,t,{fontSize:12,fill:"$info",textGrowth:"fixed-width",width:"fill_container",lineHeight:1.4});return n;}
// site pieces
function sCheck(p,label,count,on,o={}){const r=fr(p,"Opt "+label,{width:"fill_container",gap:10,alignItems:"center",height:28,...(o.dis?{opacity:0.4}:{})});const b=fr(r,"Box",{width:18,height:18,cornerRadius:o.radio?999:4,stroke:on?SC.acc:SC.line,strokeWidth:1.5,fill:on?SC.acc:SC.white,alignItems:"center",justifyContent:"center"});if(on)ic(b,o.radio?"circle":"check",{width:11,height:11,fill:SC.white});stx(r,label,{fontSize:14});sp(r);if(count!==null&&count!==undefined)tx(r,String(count),{fontSize:13,fill:SC.soft});return r;}
function sGroup(p,title,o={}){const g=fr(p,"Group "+title,{layout:"vertical",width:"fill_container",gap:6,padding:[0,0,16,0],stroke:SC.line,strokeWidth:{bottom:o.last?0:1},...(o.sel?{stroke:"#EA580C",strokeWidth:2,padding:10,cornerRadius:8}:{})});const h=fr(g,"Legend",{width:"fill_container",alignItems:"center",padding:[0,0,4,0]});stx(h,title,{fontSize:15,fontWeight:"700"});sp(h);ic(h,"chevron-up",{width:14,height:14,fill:SC.soft});if(o.sel){const t=fr(g,"Sel tag",{padding:[1,6],cornerRadius:4,fill:"#EA580C"});tx(t,"Selected in builder",{fontSize:10,fontWeight:"600",fill:"#FFF7ED"});}return g;}
function sSearch(p,val,o={}){const f=fr(p,"Search box",{width:o.w||"fill_container",height:40,padding:[0,12],gap:8,cornerRadius:999,stroke:SC.line,strokeWidth:1,fill:SC.white,alignItems:"center"});ic(f,"search",{width:16,height:16,fill:SC.soft});stx(f,val||"Search the shop",{fontSize:14,fill:val?SC.ink:SC.soft});return f;}
function sRange(p,a,b){const w=fr(p,"Range",{layout:"vertical",width:"fill_container",gap:10});const tr=fr(w,"Track",{width:"fill_container",height:4,cornerRadius:2,fill:SC.line});const bar=fr(w,"Ends",{width:"fill_container",gap:8});for(const v of [a,b]){const i=fr(bar,"In "+v,{width:"fill_container",height:36,padding:[0,10],cornerRadius:8,stroke:SC.line,strokeWidth:1,fill:SC.white,alignItems:"center"});stx(i,v,{fontSize:14});}return w;}
function sToggle(p,label,on){const r=fr(p,"Toggle "+label,{width:"fill_container",alignItems:"center",height:28});stx(r,label,{fontSize:14});sp(r);const t=fr(r,"Switch",{width:36,height:20,cornerRadius:999,fill:on?SC.acc:SC.line,padding:2,justifyContent:on?"end":"start"});fr(t,"Knob",{width:16,height:16,cornerRadius:999,fill:SC.white});return r;}
function sChip(p,t){const c=fr(p,"Chip "+t,{padding:[6,10],gap:6,cornerRadius:999,fill:SC.accSoft,alignItems:"center"});tx(c,t,{fontSize:13,fontWeight:"500",fill:SC.acc});ic(c,"x",{width:12,height:12,fill:SC.acc});return c;}
function sBtn(p,t,o={}){const b=fr(p,"SBtn "+t,{height:o.h||40,padding:[0,16],gap:8,cornerRadius:999,alignItems:"center",justifyContent:"center",...(o.w?{width:o.w}:{}),...(o.primary?{fill:SC.ink}:{stroke:SC.line,strokeWidth:1,fill:SC.white})});if(o.icon)ic(b,o.icon,{width:16,height:16,fill:o.primary?SC.white:SC.ink});tx(b,t,{fontSize:14,fontWeight:"600",fill:o.primary?SC.white:SC.ink});if(o.count){const c=fr(b,"n",{padding:[1,7],cornerRadius:999,fill:SC.acc});tx(c,String(o.count),{fontSize:11,fontWeight:"700",fill:SC.white});}if(o.chev)ic(b,"chevron-down",{width:14,height:14,fill:SC.ink});return b;}
const PRODUCTS=[["Country sourdough","€6.50","wheat","#E8CFA9","Bread"],["Rye & caraway","€7.00","wheat","#C9A57F","Bread"],["Rosemary focaccia","€5.00","sprout","#E5D28E","Bread · Vegan"],["Butter croissant","€2.80","croissant","#EFC27B","Pastries"],["Pain au chocolat","€3.20","croissant","#D9A66A","Pastries"],["Cinnamon bun","€3.50","cookie","#D8B08A","Pastries · Vegan"],["Seeded baguette","€3.80","wheat","#E2C38F","Bread · Vegan"],["Almond croissant","€3.60","croissant","#E9C98F","Pastries"],["Spelt loaf","€6.90","wheat","#CDAE86","Bread · Vegan"]];
function prod(p,pr,o={}){const [n,price,icn,col,tag]=pr;const c=fr(p,"Product "+n,{layout:"vertical",width:"fill_container",gap:8});const im=fr(c,"Image",{width:"fill_container",height:o.ih||150,cornerRadius:12,fill:col,alignItems:"center",justifyContent:"center"});ic(im,icn,{width:o.ih&&o.ih<110?28:40,height:o.ih&&o.ih<110?28:40,fill:"#00000033"});stx(c,n,{fontSize:o.fs||15,fontWeight:"600"});const l=fr(c,"Meta",{width:"fill_container"});tx(l,tag,{fontSize:12,fill:SC.soft});sp(l);stx(l,price,{fontSize:o.fs?13:14,fontWeight:"600"});return c;}
function grid(p,cols,items,o={}){const g=fr(p,"Results grid",{layout:"vertical",width:"fill_container",gap:o.gap||20});for(let i=0;i<items.length;i+=cols){const r=fr(g,"Row",{width:"fill_container",gap:o.gap||20});for(let j=0;j<cols;j++){if(items[i+j])prod(r,items[i+j],o);else fr(r,"Empty",{width:"fill_container",height:1});}}return g;}
function siteNav(p,o={}){const h=fr(p,"Site header",{width:"fill_container",height:o.h||64,padding:[0,o.px||40],alignItems:"center",gap:24,stroke:SC.line,strokeWidth:{bottom:1},fill:SC.bg});const l=fr(h,"Logo",{gap:8,alignItems:"center"});ic(l,"croissant",{width:22,height:22,fill:SC.acc});stx(l,"Acme Bakery",{fontSize:o.small?16:18,fontWeight:"800"});sp(h);if(!o.small){for(const t of ["Shop","Weddings","Journal","Visit us"])stx(h,t,{fontSize:14,fontWeight:t=="Shop"?"700":"500"});}ic(h,o.small?"menu":"shopping-bag",{width:20,height:20,fill:SC.ink});return h;}
function browser(p,url,o={}){const b=fr(p,"Browser",{layout:"vertical",width:o.w||"fill_container",height:o.h||"fill_container",cornerRadius:10,stroke:"$border",strokeWidth:1,clip:true,fill:SC.bg});const bar=fr(b,"Chrome",{width:"fill_container",height:36,padding:[0,12],gap:8,alignItems:"center",fill:"$muted"});for(const c of ["#F87171","#FBBF24","#4ADE80"])fr(bar,"dot",{width:10,height:10,cornerRadius:999,fill:c});const u=fr(bar,"URL",{width:"fill_container",height:24,padding:[0,10],gap:6,cornerRadius:6,fill:"$bg",alignItems:"center"});ic(u,"lock",{width:12,height:12});tx(u,url,{fontSize:12,fill:"$fg",fontFamily:"Roboto Mono"});return b;}
function sidebarFilter(p,o={}){const f=fr(p,"Filter (sidebar preset)",{layout:"vertical",width:o.w||260,gap:16});
 const hd=fr(f,"Head",{width:"fill_container",alignItems:"center"});stx(hd,"Filter",{fontSize:18,fontWeight:"800"});sp(hd);tx(hd,"Reset",{fontSize:13,fontWeight:"600",fill:SC.acc});
 sSearch(f,o.q);
 const g1=sGroup(f,"Category",{sel:o.selCat});sCheck(g1,"Bread",12,true);sCheck(g1,"Pastries",9,true);sCheck(g1,"Cakes",6,false);sCheck(g1,"Gluten-free",0,false,{dis:true});
 const g2=sGroup(f,"Dietary");sToggle(g2,"Vegan only",true);
 const g3=sGroup(f,"Price");sRange(g3,"€2","€10");
 if(o.apply){sBtn(f,"Apply",{primary:true,w:"fill_container"});}
 return f;}
function resultsHead(p,count,o={}){const r=fr(p,"Results head",{layout:"vertical",width:"fill_container",gap:12});const t=fr(r,"Count and sort",{width:"fill_container",alignItems:"center",gap:12});stx(t,count,{fontSize:15,fontWeight:"600"});if(o.pending){const pd=fr(t,"Pending",{padding:[3,8],cornerRadius:999,fill:"#FEF3C7"});tx(pd,"2 changes not applied",{fontSize:12,fontWeight:"600",fill:"#92400E"});}sp(t);sBtn(t,"Sort: Price, low to high",{chev:true,h:36});if(o.chips!==false){const c=fr(r,"Active chips",{gap:8,alignItems:"center"});for(const x of ["Bread","Pastries","Vegan","€2–€10"])sChip(c,x);tx(c,"Clear all",{fontSize:13,fontWeight:"600",fill:SC.ink});}return r;}
function callout(p,n,title,body,o={}){const c=fr(p,"Callout "+n,{width:o.w||"fill_container",padding:12,gap:10,cornerRadius:10,fill:"$bg",stroke:"$border",strokeWidth:1,alignItems:"start"});const b=fr(c,"N",{width:22,height:22,cornerRadius:999,fill:"$primary",alignItems:"center",justifyContent:"center"});tx(b,String(n),{fontSize:11,fontWeight:"700",fill:"$primary-fg"});const t=fr(c,"T",{layout:"vertical",gap:3,width:"fill_container"});tx(t,title,{fontWeight:"600"});tx(t,body,{fontSize:12,fill:"$muted-fg",textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});return c;}
// builder header shared
function fHeader(m,o={}){const head=fr(m,"Filter header",{width:"fill_container",padding:[18,24,0,24],gap:12,alignItems:"center"});btn(head,null,{icon:"arrow-left",kind:"ghost"});
 const tb=fr(head,"Title",{layout:"vertical",gap:4,width:"fill_container"});const tl=fr(tb,"Line",{gap:8,alignItems:"center"});tx(tl,"Shop filter",{fontSize:20,fontWeight:"600"});badge(tl,"Draft · 2 changes","warn");badge(tl,"Structure","outline");
 const sub=fr(tb,"Sub",{gap:6,alignItems:"center"});tx(sub,"Filters the query Loop",{fontSize:12,fill:"$muted-fg"});mono(sub,"products");tx(sub,"on Shop (Page) ·",{fontSize:12,fill:"$muted-fg"});mono(sub,'{{@filter shop-filter for="products"}}');
 const md=fr(head,"Mode",{layout:"vertical",gap:2,alignItems:"end"});seg(md,["Live","On submit"],o.mode||"Live");
 btn(head,"Preview on Staging",{icon:"eye"});btn(head,"Publish Filter",{kind:"primary",icon:"upload"});
 tabsRow(m,[["Controls",{n:"7"}],["Layout"],["Settings"],["Translations",{n:"IT 3",k:"warn"}]],o.tab||"Controls",{px:24});}
const CONTROLS=[["search","Search box","Search","q"],["list-checks","Category","Checkboxes","category"],["toggle-right","Dietary","Toggle","vegan"],["move-horizontal","Price","Range","price"],["arrow-up-down","Sort","Sort","sort"],["circle-x","Active filters & Reset","Chips",null],["hash","Result count","Count",null]];
function ctrlRow(p,c,sel){const [i,n,t,k]=c;const r=fr(p,"Ctrl "+n,{width:"fill_container",padding:[8,10],gap:8,cornerRadius:8,alignItems:"center",...(sel?{fill:"$bg",stroke:"$primary",strokeWidth:2}:{fill:"$bg",stroke:"$border",strokeWidth:1})});ic(r,"grip-vertical",{width:12,height:12});ic(r,i,{width:15,height:15,fill:"$fg"});const tt=fr(r,"T",{layout:"vertical",gap:1,width:"fill_container"});tx(tt,n,{fontWeight:"500"});tx(tt,t,{fontSize:11,fill:"$muted-fg"});if(k)mono(r,k);return r;}
function previewPane(p,o={}){const pv=fr(p,"Live preview",{layout:"vertical",width:"fill_container",height:"fill_container",padding:[14,20,20,20],gap:12,fill:"$canvas"});
 const h=fr(pv,"Preview bar",{width:"fill_container",alignItems:"center",gap:8});ic(h,"radio",{width:14,height:14,fill:"$success"});tx(h,"Live preview",{fontWeight:"600"});tx(h,"· Site Design system · 48 published Products · real counts",{fontSize:12,fill:"$muted-fg"});sp(h);seg(h,["EN","IT"],"EN");seg(h,["Desktop","Phone"],o.dev||"Desktop");
 const br=browser(pv,o.url||"acmebakery.ie/shop?category=bread,pastries&vegan=1&price=2-10");return br;}
